// tb_top: the whole system (rtl/top.v) driven over its UART pins like the PC would, replaying a
// transcript generated by python/gen_vectors.py (+SCRIPT=<file>):
//   S n b...  send n bytes back to back      E n b...  the next n received bytes must equal these
//   G c       stay silent for c cycles        R 0       press and release CPU_RESET
//   X 0       end
// Received bytes are collected continuously (also during S and G), so a response that arrives
// while the host is silent (timeouts) is still checked in order.
`timescale 1ns / 1ps
module tb_top;
    parameter P = 1;
    parameter DIL_SPECIAL = 0;
    localparam CPB = 8;          // fast UART for simulation
    localparam TIMEOUT = 2000;   // inter-byte timeout in cycles (the transcript's gap is 3000)

    reg clk = 0, rstn = 0, mon_rst = 1;
    always #5 clk = ~clk;
    wire line_in, line_out;
    wire [3:0] led;
    top #(.P(P), .DIL_SPECIAL(DIL_SPECIAL), .CLKS_PER_BIT(CPB), .TIMEOUT(TIMEOUT)) dut (
        .CLK100MHZ(clk), .CPU_RESETN(rstn), .UART_TXD_IN(line_in), .UART_RXD_OUT(line_out), .LED(led)
    );

    // the "PC": a transmitter into the board and a receiver of its answers
    reg        hv = 0;
    reg  [7:0] hb = 0;
    wire       hready;
    uart_tx #(.CLKS_PER_BIT(CPB)) pc_tx (.clk(clk), .rst(mon_rst), .in_valid(hv), .in_byte(hb), .in_ready(hready), .tx(line_in));
    wire       rv, rerr;
    wire [7:0] rb;
    uart_rx #(.CLKS_PER_BIT(CPB)) pc_rx (.clk(clk), .rst(mon_rst), .rx(line_out), .out_valid(rv), .out_byte(rb), .frame_err(rerr));

    reg [7:0] rxq[0:65535];
    integer rx_wr = 0, rx_rd = 0, errors = 0;
    always @(posedge clk) begin
        if (rv) begin
            rxq[rx_wr % 65536] = rb;
            rx_wr = rx_wr + 1;
        end
        if (rerr) begin
            $display("ERROR: framing error on the board's transmit line");
            errors = errors + 1;
        end
    end

    reg [8*256-1:0] script;
    reg [8*8-1:0] tok;
    integer fs, r, n, i, v, w, xn = 0, nbytes = 0, lost = 0;
    initial begin
        if (!$value$plusargs("SCRIPT=%s", script)) begin
            $display("ERROR: +SCRIPT=<transcript> missing");
            $finish;
        end
        fs = $fopen(script, "r");
        if (fs == 0) begin
            $display("ERROR: cannot open %0s", script);
            $finish;
        end
        repeat (5) @(posedge clk);
        mon_rst <= 0;
        rstn <= 1;
        repeat (10) @(posedge clk);
        while (1) begin
            r = $fscanf(fs, "%s %d", tok, n);
            if (r != 2 || tok == "X") begin
                $fclose(fs);
                $display("%0d transcript records, %0d response bytes checked, P=%0d DIL_SPECIAL=%0d", xn, nbytes, P, DIL_SPECIAL);
                if (errors == 0 && nbytes > 0) $display("TEST PASSED");
                else $display("TEST FAILED (%0d errors)", errors);
                $finish;
            end
            xn = xn + 1;
            if (tok == "S") begin
                for (i = 0; i < n; i = i + 1) begin
                    r = $fscanf(fs, "%d", v);
                    #1;
                    while (!hready) begin @(posedge clk); #1; end
                    hv <= 1; hb <= v;
                    @(posedge clk); #1;
                    hv <= 0;
                    @(posedge clk);
                end
            end else if (tok == "E") begin
                lost = 0;
                for (i = 0; i < n; i = i + 1) begin
                    r = $fscanf(fs, "%d", v);  // always consume the expected bytes, even after a loss
                    w = 0;
                    while (!lost && rx_rd >= rx_wr && w < 200000) begin @(posedge clk); w = w + 1; end
                    if (lost) begin
                    end else if (rx_rd >= rx_wr) begin
                        $display("ERROR: record %0d: response byte %0d of %0d never arrived", xn, i, n);
                        errors = errors + 1;
                        lost = 1;
                    end else begin
                        if (rxq[rx_rd % 65536] !== v) begin
                            if (errors < 20)
                                $display("ERROR: record %0d: response byte %0d expected %0d got %0d", xn, i, v, rxq[rx_rd % 65536]);
                            errors = errors + 1;
                        end
                        rx_rd = rx_rd + 1;
                        nbytes = nbytes + 1;
                    end
                end
            end else if (tok == "G") begin
                repeat (n) @(posedge clk);
            end else if (tok == "R") begin
                rstn <= 0;
                repeat (20) @(posedge clk);
                rstn <= 1;
                repeat (20) @(posedge clk);
            end
        end
    end
endmodule
